package bowling

import "errors"

// Game keeps track of the rolls in a game of bowling.
type Game struct {
	rolls []int
}

// NewGame returns a new, empty Game.
func NewGame() *Game {
	return &Game{}
}

// Roll records a throw of the ball, validating the number of pins knocked down.
func (g *Game) Roll(pins int) error {
	if pins < 0 {
		return errors.New("negative roll is invalid")
	}
	if pins > 10 {
		return errors.New("pin count exceeds pins on the lane")
	}
	if _, pinsDown, over := g.frameState(); over {
		return errors.New("cannot roll after game is over")
	}
	if pins > 10-pinsDown {
		return errors.New("pin count exceeds pins on the lane")
	}
	g.rolls = append(g.rolls, pins)
	return nil
}

// Score returns the total score of the game.
// It is an error to call it before the game is complete.
func (g *Game) Score() (int, error) {
	if _, _, over := g.frameState(); !over {
		return 0, errors.New("score cannot be taken until the end of the game")
	}
	total := 0
	i := 0
	for frame := 0; frame < 10; frame++ {
		if g.rolls[i] == 10 { // strike
			if frame < 9 {
				total += 10 + g.rolls[i+1] + g.rolls[i+2]
			} else {
				total += g.rolls[i] + g.rolls[i+1] + g.rolls[i+2]
			}
			i++
		} else if g.rolls[i]+g.rolls[i+1] == 10 { // spare
			if frame < 9 {
				total += 10 + g.rolls[i+2]
			} else {
				total += g.rolls[i] + g.rolls[i+1] + g.rolls[i+2]
			}
			i += 2
		} else { // open frame
			total += g.rolls[i] + g.rolls[i+1]
			i += 2
		}
	}
	return total, nil
}

// frameState reports the index of the frame currently in progress (0-9),
// the number of pins already knocked down in that frame's current rack,
// and whether the game is over.
func (g *Game) frameState() (frame, pinsDown int, over bool) {
	i := 0
	for frame = 0; frame < 10; frame++ {
		if i >= len(g.rolls) {
			return frame, 0, false
		}
		if frame < 9 {
			if g.rolls[i] == 10 {
				i++ // strike: the frame is complete
			} else if i+1 < len(g.rolls) {
				i += 2 // the frame is complete
			} else {
				return frame, g.rolls[i], false // only the first roll has been made
			}
		} else if tenthFrameComplete(g.rolls[i:]) {
			return frame, 0, true
		} else {
			// The tenth frame is in progress; the pins down depend on
			// which of its rolls have been made.
			tenth := g.rolls[i:]
			switch {
			case len(tenth) == 1:
				if tenth[0] == 10 {
					return frame, 0, false // first bonus roll: fresh rack
				}
				return frame, tenth[0], false
			case tenth[0] == 10:
				if tenth[1] == 10 {
					return frame, 0, false // second bonus roll: fresh rack
				}
				return frame, tenth[1], false
			default: // spare: the bonus roll is a fresh rack
				return frame, 0, false
			}
		}
	}
	return 10, 0, true
}

// tenthFrameComplete reports whether the given rolls complete the tenth frame.
// A strike or spare in the tenth frame requires a third (bonus) roll;
// an open frame is complete with two rolls.
func tenthFrameComplete(tenth []int) bool {
	if len(tenth) < 2 {
		return false
	}
	if tenth[0] == 10 || tenth[0]+tenth[1] == 10 { // strike or spare
		return len(tenth) >= 3
	}
	return true
}

